from hypothesis import given, strategies as st

def naar_regel(velden):        # schrijf een rij weg
    return ";".join(velden)

def uit_regel(regel):          # lees de rij terug
    return regel.split(";")

@given(st.lists(st.text(), min_size=1))
def test_heen_en_terug(velden):
    assert uit_regel(naar_regel(velden)) == velden

test_heen_en_terug()
